import java.io.*;
import java.util.*;

public class C421 {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        int l = in.nextInt() - 1;
        int r = in.nextInt() - 1;

        int len = a + b;
        int ans;
        if (r - l >= 2 * len) {
            ans = Math.max(a + 1, 2 * a - b);
        } else {
            r -= len * (l / len);
            l %= len;
            ans = countLetters(a, b, l, r);
        }
        System.out.println(ans);
    }

    static int countLetters(int a, int b, int l, int r) {
        boolean[] seen = new boolean[30];
        for (int i = l; i <= r; ++i) {
            seen[charAt(a, b, l, i) - 'a'] = true;
        }
        int ans = 0;
        for (boolean v : seen) {
            if (v) {
                ++ans;
            }
        }
        return ans;
    }

    static char charAt(int a, int b, int l, int idx) {
        int len = a + b;
        if (idx >= 2 * len) {
            return partA(a, b, l, idx - 2 * len);
        }
        if (idx >= len) {
            if (idx >= len + a) {
                return blockB(a, b, l, Math.min(b, a - 1));
            }
            return blockB(a, b, l, idx - len);
        }
        return partA(a, b, l, idx);
    }

    static char partA(int a, int b, int l, int idx) {
        if (idx < a) {
            return (char) ('a' + idx);
        }
        char fill = l < a ? (char) ('a' + a - 1) : (char) ('a' + (b < a ? b : a - 1));
        return fill;
    }

    static char blockB(int a, int b, int l, int pos) {
        boolean[] used = new boolean[30];
        int len = a + b;
        for (int i = 0; i < a; ++i) {
            used[partA(a, b, l, len - 1 - i) - 'a'] = true;
        }
        int ptr = 0;
        for (int i = 0; i < pos; ++i) {
            while (used[ptr]) {
                ++ptr;
            }
            used[ptr] = true;
        }
        while (used[ptr]) {
            ++ptr;
        }
        return (char) ('a' + ptr);
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == -1) {
                throw new InputMismatchException();
            }
            if (this.curChar >= this.numChars) {
                this.curChar = 0;
                try {
                    this.numChars = this.stream.read(this.buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (this.numChars <= 0) {
                    return -1;
                }
            }
            return this.buf[this.curChar++];
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
            }
            byte sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = this.read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res *= 10;
                res += c - '0';
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }
            throw new InputMismatchException();
        }

        public static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
